import{_ as t,a as o}from"./chunks/accelerometer_positions_px4.D_HO4Tg3.js";import{_ as a,o as i,c as l,al as r}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"加速度计校准","description":"","frontmatter":{},"headers":[],"relativePath":"zh/config/accelerometer.md","filePath":"zh/config/accelerometer.md"}'),s={name:"zh/config/accelerometer.md"};function n(c,e,p,d,m,h){return i(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="加速度计校准" tabindex="-1">加速度计校准 <a class="header-anchor" href="#加速度计校准" aria-label="Permalink to &quot;加速度计校准&quot;">​</a></h1><p>加速度计必须在首次使用或飞行控制器方向发生改变时进行校准。 否则通常无需重新校准（除非在冬季使用时， 飞行控制器出厂时未进行温度校准<a href="./../advanced_config/sensor_thermal_calibration">thermally calibrated</a>）。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>加速度计校准不良通常会被飞行前检查和拒绝解锁提示所捕获（GQC 的警告信息通常显示为“加速度计零偏过高” 和 “一致性检查失败”）。</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>这与<a href="./../config/compass">罗盘校准</a> 类似，区别在于每个姿态下需要将机体保持静止（而非旋转）。</p></div><h2 id="执行校准" tabindex="-1">执行校准 <a class="header-anchor" href="#执行校准" aria-label="Permalink to &quot;执行校准&quot;">​</a></h2><p><em>QGroundControl</em> will guide you to place and hold your vehicle in a number of orientations (you will be prompted when to move between positions).</p><p>The calibration steps are:</p><ol><li><p>Start <em>QGroundControl</em> and connect the vehicle.</p></li><li><p>Select <strong>&quot;Q&quot; icon &gt; Vehicle Setup &gt; Sensors</strong> (sidebar) to open <em>Sensor Setup</em>.</p></li><li><p>Click the <strong>Accelerometer</strong> sensor button.</p><p><img src="'+t+'" alt="Accelerometer calibration"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You should already have set the <a href="./../config/flight_controller_orientation">Autopilot Orientation</a>. If not, you can also set it here.</p></div></li></ol><p>:::</p><ol start="4"><li><p>Click <strong>OK</strong> to start the calibration.</p></li><li><p>Position the vehicle as guided by the <em>images</em> on the screen. Once prompted (the orientation-image turns yellow) hold the vehicle still. 该位置标定完成后，屏幕上的相应图示将变成绿色。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The calibration uses a least squares &#39;fit&#39; algorithm that doesn&#39;t require you to have &quot;perfect&quot; 90 degree orientations. Provided each axis is pointed mostly up and down at some time in the calibration sequence, and the vehicle is held stationary, the precise orientation doesn&#39;t matter.</p></div></li></ol><p>:::</p><p><img src="'+o+'" alt="Accelerometer calibration"></p><ol start="6"><li>在机体的所有方向上重复校准步骤。</li></ol><p>Once you&#39;ve calibrated the vehicle in all the positions <em>QGroundControl</em> will display <em>Calibration complete</em> (all orientation images will be displayed in green and the progress bar will fill completely). You can then proceed to the next sensor.</p><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/sensors_px4.html#accelerometer" target="_blank" rel="noreferrer">QGroundControl User Guide &gt; Sensors</a></li><li><a href="https://youtu.be/91VGmdSlbo4?t=1m46s" target="_blank" rel="noreferrer">PX4 Setup Video - @1m46s</a> (Youtube)</li></ul>',16)])])}const f=a(s,[["render",n]]);export{_ as __pageData,f as default};
